// DEMO SOURCE so the template runs immediately. For production,
// disable this node and read your appointments from Google Sheets.
// Required columns: appointment_id, customer_name, phone, starts_at
// (ISO), practitioner, treatment, status
const demoRows = [
  {
    appointment_id: 'APT-2001',
    customer_name: 'Anna Voorbeeld',
    phone: '+316****5678',
    starts_at: new Date(Date.now() + 100 * 60 * 1000).toISOString(),
    practitioner: 'Stylist A',
    treatment: 'Hair treatment',
    status: 'unconfirmed'
  },
  {
    // broken on purpose: missing phone -> routed to the error log
    appointment_id: 'APT-2002',
    customer_name: 'Tom Voorbeeld',
    starts_at: new Date(Date.now() + 26 * 3600 * 1000).toISOString(),
    practitioner: 'Dr. Voorbeeld',
    treatment: 'Intake',
    status: 'unconfirmed'
  },
  {
    appointment_id: 'APT-2003',
    customer_name: 'Sara Voorbeeld',
    phone: '+316****3344',
    starts_at: new Date(Date.now() + 3 * 3600 * 1000).toISOString(),
    practitioner: 'Stylist A',
    treatment: 'Consultation',
    status: 'confirmed'
  }
];
return demoRows.map((row) => ({ json: row }));

// Placeholder for the WhatsApp Business Cloud send node.
// After import: add 'Send Message' (WhatsApp Business Cloud) here with your
// credentials, wire In window -> Send -> Wait For Reply, then delete this node.
const items = $input.all();
return items.map((item) => ({
    json: { ...item.json, sent_at: new Date().toISOString(), transport: 'whatsapp_demo' }
}));

// Classify the reply webhook body. The Wait node is resumed by a
// webhook (resume: webhook API) whose body lands here.
const items = $input.all();
const out = [];
for (const item of items) {
  const b = item.json;
  const text = String(b.Body || b.text || '').trim().toUpperCase();
  let verdict = 'no_reply';
  if (/^(JA|J|YES|Y|OK|CONFIRM|C)([\s!.,]|$)/.test(text)) verdict = 'confirmed';
  else if (/^(NEE|N|NO|RESCHEDULE|CANCEL|WIJZIG)([\s!.,]|$)/.test(text)) verdict = 'cancel_requested';
  else if (text) verdict = 'unclear';
  out.push({
    json: {
      appointment_id: b.appointment_id || 'unknown',
      from: b.From || b.from || '',
      raw_text: text,
      verdict: verdict
    }
  });
}
return out;

// Validate each appointment row before anything is sent: a missing id or
// phone, or an unparseable start time, would silently break the rescue.
// Bad rows are routed to the error log with the exact reason; good rows
// get a precomputed minutes_until the window gate reads.
const items = $input.all();
const out = [];
for (const item of items) {
  const r = item.json;
  const t = r.starts_at ? new Date(r.starts_at).getTime() : NaN;
  let rowError = null;
  if (!r.appointment_id) rowError = 'missing appointment_id';
  else if (isNaN(t)) rowError = 'starts_at not parseable';
  else if (!r.phone) rowError = 'missing phone';
  else if (r.status && !['unconfirmed', 'confirmed', 'cancelled'].includes(r.status)) rowError = 'unknown status: ' + r.status;
  out.push({
    json: {
      ...r,
      starts_ts: isNaN(t) ? null : t,
      minutes_until: isNaN(t) ? null : Math.round((t - Date.now()) / 60000),
      row_valid: !rowError,
      row_error: rowError
    }
  });
}
return out;

// Error path: broken source rows land here with the exact reason instead
// of silently vanishing. In production, write to a 'rescue_errors' sheet
// so a human can fix the source data.
const items = $input.all();
return items.map((item) => ({
  json: {
    error: 'invalid appointment row',
    appointment_id: item.json.appointment_id || null,
    reason: item.json.row_error || 'unknown',
    seen_at: new Date().toISOString()
  }
}));

// Rows outside the 90-150 minute window, or already confirmed, pass by
// harmlessly. They stay in the sheet; the next hourly run picks them up
// when their time comes.
const items = $input.all();
return items.map((item) => ({
  json: {
    skipped: true,
    appointment_id: item.json.appointment_id,
    minutes_until: item.json.minutes_until,
    status: item.json.status,
    skipped_at: new Date().toISOString()
  }
}));

// One check-in per appointment, guaranteed twice: the 90-150 minute
// window plus this static-data guard. If the workflow fires twice inside
// the band (manual run, timezone shift), the second run skips silently.
const staticData = $getWorkflowStaticData('global');
staticData.checked_in = staticData.checked_in || {};
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (staticData.checked_in[r.appointment_id]) continue;
  staticData.checked_in[r.appointment_id] = new Date().toISOString();
  const dateStr = new Date(r.starts_ts).toLocaleString('en-GB', {
    hour: '2-digit', minute: '2-digit'
  });
  const hrs = Math.round(r.minutes_until / 60);
  out.push({ json: {
    appointment_id: r.appointment_id,
    customer_name: r.customer_name,
    to: r.phone,
    channel: 'whatsapp',
    minutes_until: r.minutes_until,
    message: 'Hi ' + r.customer_name + ', your ' + r.treatment + ' appointment with ' + r.practitioner + ' is in about ' + hrs + ' hour(s) at ' + dateStr + '. Can you make it? Reply YES or NO. No reply means we release your slot.'
  }});
}
return out;

// Placeholder for your calendar/sheet update. After import: put a Google
// Calendar or Sheets update here to mark the appointment confirmed, then
// delete this node.
const items = $input.all();
return items.map((item) => ({
    json: { ...item.json, marked_at: new Date().toISOString(), mark_action: 'confirmed' }
}));

// Placeholder for the staff follow-up: cancel requests, unclear replies
// and no-replies need a human. After import: wire this to Slack, email or
// a 'needs_attention' sheet, then delete this node.
const items = $input.all();
return items.map((item) => ({
    json: { ...item.json, flagged_at: new Date().toISOString(), needs_staff: true }
}));
